CREATE TYPE public.app_role AS ENUM ('admin', 'user');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id, role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own roles" ON public.user_roles FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = _user_id AND role = _role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid, public.app_role) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.has_role(uuid, public.app_role) TO authenticated;
CREATE TABLE public.competition_photos (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), storage_path text NOT NULL UNIQUE, caption text NOT NULL CHECK (char_length(caption) BETWEEN 1 AND 500), event_name text NOT NULL CHECK (char_length(event_name) BETWEEN 1 AND 150), created_by uuid NOT NULL DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.competition_photos TO anon;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.competition_photos TO authenticated;
GRANT ALL ON public.competition_photos TO service_role;
ALTER TABLE public.competition_photos ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public competition gallery" ON public.competition_photos FOR SELECT TO anon, authenticated USING (true);
CREATE POLICY "Admin upload metadata" ON public.competition_photos FOR INSERT TO authenticated WITH CHECK (public.has_role(auth.uid(), 'admin') AND created_by = auth.uid());
CREATE POLICY "Admin edit gallery" ON public.competition_photos FOR UPDATE TO authenticated USING (public.has_role(auth.uid(), 'admin')) WITH CHECK (public.has_role(auth.uid(), 'admin'));
CREATE POLICY "Admin delete gallery" ON public.competition_photos FOR DELETE TO authenticated USING (public.has_role(auth.uid(), 'admin'));
CREATE POLICY "Read published competition files" ON storage.objects FOR SELECT TO anon, authenticated USING (bucket_id = 'competition-photos' AND EXISTS (SELECT 1 FROM public.competition_photos WHERE storage_path = name));
CREATE POLICY "Admin read competition files" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'competition-photos' AND public.has_role(auth.uid(), 'admin'));
CREATE POLICY "Admin upload competition files" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'competition-photos' AND public.has_role(auth.uid(), 'admin') AND lower(storage.extension(name)) IN ('jpg','jpeg','png','webp'));
CREATE POLICY "Admin delete competition files" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'competition-photos' AND public.has_role(auth.uid(), 'admin'));